function editorialReference(now = new Date()) {
 const execution_date=now.toISOString();
 const editorial_timezone='America/Fortaleza';
 const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:editorial_timezone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(now).filter(p=>p.type!=='literal').map(p=>[p.type,p.value]));
